// Igual à versão vulnerável: só encanamento.
// Aceita o JSON da WhatsApp Cloud API ou { telefone, mensagem } para teste local.
const body = $input.first().json.body ?? $input.first().json;

let telefone = body.telefone ?? null;
let mensagem = body.mensagem ?? null;
let nome = body.nome ?? 'cliente';

const msg = body?.entry?.[0]?.changes?.[0]?.value?.messages?.[0];
const contato = body?.entry?.[0]?.changes?.[0]?.value?.contacts?.[0];
if (msg) {
  telefone = '+' + String(msg.from).replace(/^\+/, '');
  mensagem = msg.text?.body ?? '[mensagem sem texto]';
  nome = contato?.profile?.name ?? 'cliente';
}

return [{ json: { telefone, mensagem, nome, recebido_em: new Date().toISOString() } }];

// ===============================================================
// O NÓ DO §21 — o conserto que sozinho resolve metade da lista.
//
// O telefone que a Meta entregou pelo webhook vira o DONO DA SESSÃO.
// Daqui pra frente, autorização é decisão de código: nenhuma ferramenta
// recebe identidade escrita pelo modelo, nem pelo texto da conversa.
//
// Também é aqui que entram os limites contáveis do §22.
// ===============================================================

const LIMITE_CARACTERES = Number($env.LIMIT_BODY_CHARS ?? 2000);
const entrada = $input.first().json;

// 1. A identidade vem do canal, não do texto.
const telefone = String(entrada.telefone ?? '').trim();
const e164 = /^\+[1-9]\d{7,14}$/;

if (!e164.test(telefone)) {
  return [{ json: {
    autorizado: false,
    erro: 'sessao_nao_identificada',
    resposta: 'Não consegui identificar o seu número. Fale com a gente pelo WhatsApp oficial da LumenShop.',
  } }];
}

// 2. Limite de tamanho da mensagem (ataque 6).
const mensagemCrua = String(entrada.mensagem ?? '');
if (mensagemCrua.length > LIMITE_CARACTERES) {
  return [{ json: {
    autorizado: false,
    erro: 'mensagem_grande_demais',
    telefone,
    tamanho: mensagemCrua.length,
    resposta: 'Sua mensagem é longa demais para o atendimento automático. Manda em partes menores, por favor.',
  } }];
}

// 3. A mensagem do cliente é DADO, não ordem: vai delimitada para o modelo.
const mensagem = mensagemCrua.replace(/\u0000/g, '').trim();

return [{ json: {
  autorizado: true,
  telefone,
  nome: entrada.nome ?? 'cliente',
  mensagem,
  sessao: telefone,
  recebido_em: new Date().toISOString(),
} }];

// §22, terceira regra: trate a saída do modelo como entrada suspeita.
// O modelo pode ter sido convencido de qualquer coisa. Antes de mandar
// o texto pro cliente, a gente valida — e registra quando barra.

const LIMITE_RESPOSTA = 1200;
const ctx = $('Montar Contexto Seguro').first().json;
let texto = String($input.first().json.output ?? '').trim();
const alertas = [];

// 1. Vazamento de configuração: se a resposta parecer o próprio prompt, corta.
const marcasDePrompt = [
  /REGRAS QUE VOC[ÊE] N[ÃA]O PODE NEGOCIAR/i,
  /system\s*message/i,
  /toolDescription/i,
  /CUPONS PERMITIDOS/i,
  /<mensagem_do_cliente>/i,
];
if (marcasDePrompt.some((r) => r.test(texto))) {
  alertas.push('possivel_vazamento_de_prompt');
  texto = 'Não posso compartilhar a minha configuração. Mas posso te ajudar com o seu pedido — me diz o número dele?';
}

// 2. Desconto fora da lista fixa: o texto não pode prometer o que o código não aplica.
const percentuais = [...texto.matchAll(/(\d{1,3})\s*%/g)].map((m) => Number(m[1]));
const permitidos = new Set((ctx.cupons_permitidos ?? []).map(String));
const percentuaisValidos = new Set((ctx.percentuais_permitidos ?? [0, 10, 15, 20]).map(Number));
if (percentuais.some((p) => p > 0 && !percentuaisValidos.has(p))) {
  alertas.push('desconto_fora_da_lista');
  texto = 'Não consigo aplicar esse desconto. Os cupons disponíveis para o seu pedido são: ' + [...permitidos].join(', ') + '.';
}

// 3. Tamanho: resposta gigante é custo e é bandeira vermelha.
if (texto.length > LIMITE_RESPOSTA) {
  alertas.push('resposta_truncada');
  texto = texto.slice(0, LIMITE_RESPOSTA) + '…';
}

// 4. Registre tudo (§22, quarta regra).
console.log(JSON.stringify({
  ts: new Date().toISOString(),
  modo: 'hardened',
  sessao: String(ctx.telefone ?? '').replace(/\d(?=\d{4})/g, '*'),
  tamanho_resposta: texto.length,
  alertas,
}));

return [{ json: { resposta: texto, alertas } }];
